// CannaQMS Starter Document Library — 15 generic, pre-approved controlled
// documents (13 SOPs + Quality Manual + Quality Policy) that give a new facility
// a working QMS on day one. Generated from the reviewed generic .docx library.
//
// These are seeded as Approved (Effective) controlled documents flagged with
// is_starter_default = true so the whole set is identifiable and REMOVABLE if a
// facility brings its own. Purpose -> description, Scope -> scope, and the rest of
// the procedure body -> body_markdown (rendered read-only in the document viewer).
//
// Seeding/removal are Admin-only and idempotent (see routes/admin.ts).
import { db } from "@workspace/db";
import { documentsTable, documentRevisionsTable, auditLogTable } from "@workspace/db";
import { and, eq, like } from "drizzle-orm";
import { facilityDateStr } from "./facilityDate";

export interface StarterDoc {
  key: string;
  title: string;
  documentType: string;
  department: string;
  ownerName: string;
  description: string;
  scope: string;
  bodyMarkdown: string;
}

// Same prefix map as routes/documents.ts generateDocNumber, plus "Manual" (MAN).
const TYPE_PREFIXES: Record<string, string> = {
  SOP: "SOP",
  "Work Instruction": "WI",
  Form: "FORM",
  Policy: "POL",
  Manual: "MAN",
  Specification: "SPEC",
  Protocol: "PROT",
  Report: "RPT",
  Other: "DOC",
};

const SEED_AUTHOR = "CannaQMS Starter Library";

function addYears(d: Date, years: number): Date {
  const r = new Date(d);
  r.setFullYear(r.getFullYear() + years);
  return r;
}

