type Actor = { id?: number; fullName: string };

// Idempotent: skips any starter doc whose title already exists as a starter
// default. Numbers each doc with the app's own scheme (SOP-YY-NNNN etc.),
// continuing from the current MAX per prefix so it never collides with
// user-created documents.
export async function seedStarterDocuments(actor: Actor) {
  return await db.transaction(async (tx) => {
    const created: { docNumber: string; title: string }[] = [];
    const skipped: string[] = [];
    const seqByPrefix = new Map<string, number>();
    const year = new Date().getFullYear().toString().slice(-2);

    for (const sd of STARTER_DOCUMENTS) {
      const [exists] = await tx
        .select({ id: documentsTable.id })
        .from(documentsTable)
        .where(and(eq(documentsTable.title, sd.title), eq(documentsTable.isStarterDefault, true)))
        .limit(1);
      if (exists) { skipped.push(sd.title); continue; }

      const prefix = TYPE_PREFIXES[sd.documentType] ?? "DOC";
      if (!seqByPrefix.has(prefix)) {
        const fullPrefix = `${prefix}-${year}-`;
        const rows = await tx
          .select({ docNumber: documentsTable.docNumber })
          .from(documentsTable)
          .where(like(documentsTable.docNumber, `${fullPrefix}%`));
        let maxSeq = 0;
        for (const r of rows) {
          const m = r.docNumber.match(/-(\d+)$/);
          if (m) { const n = parseInt(m[1], 10); if (Number.isFinite(n) && n > maxSeq) maxSeq = n; }
        }
        seqByPrefix.set(prefix, maxSeq);
      }
      const seq = (seqByPrefix.get(prefix) ?? 0) + 1;
      seqByPrefix.set(prefix, seq);
      const docNumber = `${prefix}-${year}-${String(seq).padStart(4, "0")}`;

      const now = new Date();
      const today = facilityDateStr(now);
      const nextReview = facilityDateStr(addYears(now, 3));

      const [doc] = await tx
        .insert(documentsTable)
        .values({
          docNumber,
          title: sd.title,
          documentType: sd.documentType,
          revision: "A",
          status: "Approved",
          ownerName: sd.ownerName,
          department: sd.department,
          description: sd.description,
          scope: sd.scope,
          bodyMarkdown: sd.bodyMarkdown,
          effectiveDate: today,
          approvalDate: today,
          approvedByName: SEED_AUTHOR,
          reviewIntervalYears: 3,
          nextReviewDate: nextReview,
          reviewDate: nextReview,
          summaryOfChanges: "Initial starter document",
          createdByName: SEED_AUTHOR,
          isStarterDefault: true,
        })
        .returning();

      await tx.insert(documentRevisionsTable).values({
        documentId: doc.id,
        revision: "A",
        status: "Approved",
        summaryOfChanges: "Initial starter document",
        authorName: SEED_AUTHOR,
        approvedByName: SEED_AUTHOR,
        approvalDate: today,
        effectiveDate: today,
      });

      await tx.insert(auditLogTable).values({
        tableName: "documents",
        rowId: doc.id,
        operation: "SEED_STARTER",
        changedBy: actor.id,
        changedByName: actor.fullName,
        beforeState: null as never,
        afterState: { docNumber, title: sd.title } as never,
      });

      created.push({ docNumber, title: sd.title });
    }
    return { created, skipped };
  });
}

// Removes the starter set. Only untouched starter docs (still Approved rev A and
// not cancelled) are removed; any a facility has begun revising/using are left
// alone and reported as skipped. Default = mark Obsolete (retained for history);
// purge = hard-delete (cascades revisions/sections) for a clean slate.
export async function removeStarterDocuments(actor: Actor, opts: { purge?: boolean } = {}) {
  return await db.transaction(async (tx) => {
    const rows = await tx.select().from(documentsTable).where(eq(documentsTable.isStarterDefault, true));
    const removed: string[] = [];
    const skipped: { docNumber: string; reason: string }[] = [];
    const now = new Date();

    for (const d of rows) {
      if (d.cancelledAt || d.status !== "Approved" || d.revision !== "A") {
        skipped.push({ docNumber: d.docNumber, reason: "in use or modified" });
        continue;
      }
      if (opts.purge) {
        await tx.delete(documentsTable).where(eq(documentsTable.id, d.id));
      } else {
        await tx
          .update(documentsTable)
          .set({
            status: "Obsolete",
            obsoletedAt: now,
            obsoletedByName: `${SEED_AUTHOR} (removed)`,
            obsoletedMeaning: "Starter document set removed by Admin.",
            updatedAt: now,
          })
          .where(eq(documentsTable.id, d.id));
      }
      await tx.insert(auditLogTable).values({
        tableName: "documents",
        rowId: d.id,
        operation: opts.purge ? "REMOVE_STARTER_PURGE" : "REMOVE_STARTER",
        changedBy: actor.id,
        changedByName: actor.fullName,
        beforeState: { status: d.status } as never,
        afterState: { removed: true, purge: !!opts.purge } as never,
      });
      removed.push(d.docNumber);
    }
    return { removed, skipped, purge: !!opts.purge };
  });
}
